async function main({ data1 }) {

  // ========== 统一化函数：把不同来源的字段转换成同一结构 ==========
  const normalize = (title, content, link, media, date) => ({
    title: String(title || '').trim(),
    content: String(content || '').trim(),
    link: String(link || '').trim(),
    media: String(media || '').trim(),
    publish_date: String(date || '').trim()
  });

  // ========== 数据源1：天聚AI资讯接口 ==========
  const source1 = (Array.isArray(data1) ? data1 : []).map(item =>
    normalize(
      item.title,        // 标题
      item.description,  // 摘要
      item.url,          // 链接
      item.source,       // 来源
      item.ctime         // 时间
    )
  );

  // 合并所有数据源（以后加新源，在这里扩展即可）
  const unified = [...source1];

  // ========== 拼接成喂给AI的文本 ==========
  const unified_text = unified
    .map((item, i) =>
      `${i + 1}. 【${item.title}】\n摘要：${item.content}\n来源：${item.media}｜时间：${item.publish_date}\n链接：${item.link}`
    )
    .join('\n\n');

  return { unified, unified_text };
}
